#!/usr/bin/env python3
"""Four-page proposal grounded in the frozen, native 3D MetaUrban pilot."""
import json
from pathlib import Path
from build_proposal import Doc,ROOT,OUT

def build():
 evidence=json.loads((ROOT/'outputs/streetscape/tables/summary.json').read_text())
 data={r['method']:r for r in evidence['summary'] if r['density']=='all'}
 assert all(r['n']==20 for r in data.values())
 d=Doc()
 d.p('Pedestrian-aware yielding in simulated urban streetscapes','Title')
 d.p('Mini research proposal with a reproducible three-dimensional pilot',size=23)
 d.p('UCMP-MB · Week 3 · Option 1 · Individual assignment · 2 November 2026','Caption')
 d.p('1. Research question and urban relevance','Heading')
 d.p('Does a small pedestrian-aware yielding layer improve the balance between waypoint completion, pedestrian contact and close-proximity exposure when a fixed robot policy moves through a simulated urban intersection? Does short-horizon prediction improve on distance-only yielding at two crowd sizes? The application is travel to an inspection waypoint. The demonstration navigates, stops and records a view; identifying objects or performing manipulation remains outside scope.')
 d.image(ROOT/'outputs/streetscape/figures/scene_pair.png')
 d.p('Figure 1. Actual native MetaUrban RGB views: static reproduction, seed 30 (left), and a first-person dynamic run, seed 900 with five pedestrians (right). Roads, crossings, furniture and agents are three-dimensional objects. The cameras document the simulation; policy input is state/LiDAR.','Caption')
 d.p('Shared pedestrian space creates a public-access problem. A service robot may reach its destination while passing too close to people, or avoid encounters by waiting so often that it becomes ineffective. Human-aware navigation therefore concerns the relation between movement, task progress and other users [2,5]. Urban informatics contributes the measurement perspective: trajectories are spatial interaction data, and their spatial support, temporal resolution and proxy definitions determine what a reported improvement means.')
 d.p('This proposal treats proximity as a limited geometric indicator. It does not assume that one distance threshold captures comfort across cultures, ages or mobility needs. A wheelchair-shaped mobile agent is used because it matches the released navigation checkpoint. The experiment is not a humanoid locomotion system or a vision-language-action model. Its urban scope is a synthetic pedestrian intersection, without claims about a particular real city.')
 d.p('2. Background and contribution','Heading')
 d.p('MetaUrban provides generated streetscapes and navigation tasks for urban micromobility [1]. Its public PointNav checkpoint uses proximal policy optimization (PPO) [3]. Here that checkpoint is kept fixed and evaluated in a dynamic pedestrian scene: this is a transfer experiment, not a claim that a SocialNav policy was reproduced. The contribution is a controlled, small-module comparison and a concrete proposal for improving when yielding should activate. No additional network training is required.')
 d.page()
 d.p('3. Data, spatial units and implemented methods','Heading')
 d.p('The data are synthetic state/action trajectories and RGB frames generated by official MetaUrban source, pinned to commit 6b8ff9a. The public tiny scene bundle and native pedestrian models are imported offline with recorded hashes. Local coordinates are measured in metres; they have no geographic reference system. A decision step is the observation unit, a complete navigation episode is the outcome unit, and a matched pair of crowd size and scene seed is the comparison unit.')
 d.table([['Element','Frozen pilot specification'],['Environment','Native three-dimensional intersection (map X), sidewalks, crossings, street furniture and Bullet physics; object density parameter 0.3'],['Robot and observations','Official wheelchair embodiment; fixed PointNav PPO weights; 271-dimensional state/LiDAR input; steering and throttle/brake actions'],['Crowds','5 or 15 native pedestrians; other moving traffic disabled; original ORCA-based path generation retained'],['Time and completion','0.1 s decision interval; 600-step / 60 s limit; native arrival: >95% route completion or its short-route branch, subject to out-of-road rules'],['Development and test','Development seeds 900–901; disjoint test seeds 100–109; 3 methods × 2 crowd sizes × 10 seeds = 60 test episodes']],[2200,7706])
 d.p('The baseline directly executes the deterministic PPO action, with reverse motion disabled uniformly across methods. This restriction differs from the published manual demonstration and is part of the tested transfer setting. Distance yielding uses current separation; predictive yielding uses closest approach under constant velocities over 2 s, supplemented by forward intent when accelerating from rest. Risk must clear a 0.25 m release margin for 0.5 s, and the cap recovers at at most 1 m/s². Both layers retain PPO steering and modify longitudinal control only when active.')
 d.p('For both layers, the cap ranges from 0 to 2 m/s between separation thresholds of 0.5 and 1.5 m; fully released control passes the original action through. A finite wheel-brake hold below 0.5 m/s prevents the low-speed creep observed during development. It neither relocates the robot nor forcibly sets its velocity to zero. The layer uses exact simulator states; it does not implement pedestrian detection from the RGB images.')
 d.p('The separation proxy uses the robot’s circumscribed radius (0.901 m) and the pedestrian class’s declared radius (0.35 m). It is not mesh distance or a universal collision envelope. Recorded outcomes include native arrival, pedestrian contact, any contact, path length, duration, waiting and intervention steps. Close exposure is the fraction of decision samples with proxy separation below 1 m, averaged by episode. Native pedestrians are tagged as vehicles in Bullet; in the traffic-free pedestrian setup, contact attribution therefore includes both native human and vehicle contact flags, while preserving the raw flags in the logs.')
 d.p('The same scene, initial states and planned route are required across methods for each test condition. Parameters and source hashes are frozen before testing. Completion time is compared only on the same jointly successful conditions, and collision-free completion is reported separately from arrival. Rendering/physics repeatability and finite braking were checked with real rollouts.')
 d.page()
 d.p('4. Preliminary evidence from the frozen 3D test','Heading')
 table=[['Method','Goals / 20','Ped. contact','Contact-free goals','Near time']]
 for m,name in [('baseline','PPO baseline'),('distance','Distance yield'),('predictive','Predictive yield')]:
  r=data[m];table.append([name,r['goals'],r['pedestrian_contacts'],r['collision_free_goals'],f"{100*r['mean_near_fraction']:.2f}%"])
 d.table(table,[2500,1500,1700,2300,1906])
 d.p('Each method has 20 matched conditions (10 per crowd size). Contacts are counted once per episode. “Contact-free” excludes all recorded native contact types; arrival alone does not imply safe completion. Near time is an episode-level sampled proxy, not a comfort score.','Caption')
 d.image(ROOT/'outputs/streetscape/figures/outcomes.png')
 d.p('Figure 2. Actual test outcomes from the frozen native three-dimensional simulation. All required conditions are retained, including timeouts and contact episodes. These descriptive bars do not establish statistical significance or real-world safety.','Caption')
 b,x,y=[data[m] for m in ['baseline','distance','predictive']]
 d.p(f"The baseline reached the goal in {b['goals']}/20 conditions; distance and predictive yielding reached it in {x['goals']}/20 and {y['goals']}/20. Pedestrian contacts occurred in {b['pedestrian_contacts']}, {x['pedestrian_contacts']} and {y['pedestrian_contacts']} episodes, respectively. These counts should be read with the stricter contact-free goal counts: the policies can reach a waypoint despite touching street objects or road boundaries.")
 sensitivity=evidence['nontrivial_sensitivity']
 d.p(f"A data-quality check found two matched conditions with identical start/goal coordinates and native success after one decision. All six runs remain in the frozen totals above. As a post-hoc sensitivity check, removing those same two conditions from every method leaves {sensitivity[0]['goals']}/18, {sensitivity[1]['goals']}/18 and {sensitivity[2]['goals']}/18 nontrivial completions. This distinguishes the simulator’s short-route success branch from meaningful travel.")
 n=x['nontrivial_joint_success_n']
 if n:
  d.p(f"On the same {n} nontrivial conditions completed by all three methods, distance yielding changed mean time by {x['nontrivial_paired_mean_delay_s']:+.2f} s; predictive yielding changed it by {y['nontrivial_paired_mean_delay_s']:+.2f} s. The layers intervened in {x['intervention_episodes']}/20 and {y['intervention_episodes']}/20 episodes. Predictive yielding reduced pedestrian-contact episodes by one, but did not improve total or contact-free completion. This small pilot does not establish a safety advantage.")
 else:
  d.p('No condition was jointly successful across all three methods, so a common-success completion-time comparison is not reported. This is a limitation of the transferred navigation policy, rather than evidence that a failed episode was efficient.')
 d.p('Development exposed actuator creep and prediction-induced waiting. Finite hold braking addresses the former; the test motivates a more selective route-aware rule. An additional capability demonstration (five pedestrians, seed 100) reached the goal without contact in 24.7 s, then held below 0.1 m/s for 1 s and saved a camera view. Its 1.3 s post-arrival stage is separate from navigation metrics and adds no test sample. Development videos are labelled separately from test evidence.')
 d.page()
 d.p('5. Proposed next study and expected contribution','Heading')
 d.p('The next module will use route intent to suppress false alarms: activate yielding when a predicted pedestrian trajectory enters the robot’s upcoming route corridor, rather than relying only on straight-line forward intent. Compare the unchanged PPO, distance yielding, the present predictor and the route-aware variant. Develop on new seeds 902–906, freeze parameters, then test two intersection layouts × two crowd sizes × 20 new seeds (200–219) × four methods: 320 rollouts. The current local pilot establishes environment and logging feasibility; selected RGB runs can accompany faster physics evaluation.')
 d.p('The falsifiable hypothesis is that route-aware activation reduces waiting and increases contact-free completion without increasing pedestrian contacts. Reject zero-displacement or too-short routes before control begins, and report generator failures separately. Analyse outcomes within crowd/layout strata, retain matched cases for differences, and bootstrap matched conditions for uncertainty intervals. A three-day plan is feasible: implement and verify the rule; develop and lock it; run the new test and review failures. No improvement is assumed in advance.')
 d.p('6. Limits, ethics and transferability','Heading')
 d.p('The pilot covers one intersection family and one transferred checkpoint. Poor completion can reflect both dynamic-scene transfer and the uniform reverse-motion restriction. Twenty conditions per method cannot establish rare-event safety. Pedestrians follow ORCA paths [4] with activation rules; realistic negotiation is not demonstrated. Exact state access is optimistic, and 10 Hz proximity samples can miss brief encounters. Comfort and accessibility require separate measurements. The tiny bundle omits much urban diversity, and its wheelchair visual model uses simplified vehicle dynamics rather than a calibrated real wheelchair.')
 d.p('No real street imagery or personal observations are collected. Future field validation would require an observation/consent protocol, minimal image retention and consultation with pedestrians and mobility-aid users about acceptable behaviour. Perception noise, narrow pavements, more varied bodies and local walking conventions should be tested before transfer. The practical output is an auditable decision about when a small yielding layer helps or obstructs urban navigation, with its costs and failure cases visible.')
 d.p('References','Heading')
 for text in [
  '[1] Wu, W., et al. (2025). MetaUrban: An Embodied AI Simulation Platform for Urban Micromobility. ICLR. https://arxiv.org/abs/2407.08725',
  '[2] Kruse, T., Pandey, A. K., Alami, R., & Kirsch, A. (2013). Human-aware robot navigation: A survey. Robotics and Autonomous Systems, 61(12), 1726–1743. doi:10.1016/j.robot.2013.05.007',
  '[3] Schulman, J., Wolski, F., Dhariwal, P., Radford, A., & Klimov, O. (2017). Proximal Policy Optimization Algorithms. arXiv:1707.06347.',
  '[4] van den Berg, J., Guy, S. J., Lin, M., & Manocha, D. (2011). Reciprocal n-body collision avoidance. Robotics Research, 3–19. doi:10.1007/978-3-642-19457-3_1',
  '[5] Francis, A., et al. (2023). Principles and Guidelines for Evaluating Social Robot Navigation Algorithms. arXiv:2306.16740.'
 ]:d.p(text,'Caption')
 d.save(OUT/'Week3_Streetscape_Research_Proposal.docx')

if __name__=='__main__':build()
